(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  for (let i = 0; i < 80; i++) {
    await sleep(500);
    if (document.querySelector('.tb-ok') || document.querySelector('.pj-title') || document.querySelector('.tb-error')) break;
  }
  out.notice = document.querySelector('.tb-ok')?.textContent || null;
  out.error = document.querySelector('.tb-error')?.textContent || null;
  out.openedTitle = document.querySelector('.pj-title')?.textContent || null;
  out.components = (document.querySelector('.pj-info')?.innerText || '').replace(/\s+/g, ' ').match(/使用元器件 \d+ 种/)?.[0] || null;
  out.bomRows = document.querySelectorAll('.pj-table tbody tr').length;
  out.headActions = [...document.querySelectorAll('.pj-head-actions button')].map((b) => b.textContent.trim()).filter(Boolean).join(' | ');
  out.source = (document.querySelector('.pj-meta')?.innerText || '').replace(/\s+/g, ' ');
  out.desc = (document.querySelector('.pj-card .pj-text')?.textContent || '').slice(0, 40);

  const remix = [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('做同款'));
  out.hasRemix = !!remix;
  remix?.click();
  await sleep(3500);
  out.afterRemixTitle = document.querySelector('.pj-title')?.textContent || null;
  const crumb2 = document.querySelector('.pj-crumb-link');
  if (crumb2) { crumb2.click(); await sleep(2200); }
  out.afterCount = document.querySelectorAll('.tb-project-main').length;
  out.titles = [...document.querySelectorAll('.tb-project-main h3')].map((h) => h.textContent);
  out.badges = [...document.querySelectorAll('.tb-badges')].map((e) => e.innerText.replace(/\s+/g, ' '));
  return JSON.stringify(out);
})()
